public class Solution {
  private static int best;

  /**
   * 后序遍历：向孩子要「从孩子出发、往下同值的最长单边」，
   * 在当前位置把左右两条边拼起来更新全局答案，但只向上返回单边。
   * 答案（双边）与返回值（单边）不是一回事，这是本题唯一的坑。
   */
  public static int longestUnivaluePath(TreeNode root) {
    best = 0;
    down(root);
    return best;
  }

  private static int down(TreeNode node) {
    if (node == null) return 0;
    int left = down(node.left);
    int right = down(node.right);
    int ll = 0;
    int rr = 0;
    if (node.left != null && node.left.val == node.val) ll = left + 1;
    if (node.right != null && node.right.val == node.val) rr = right + 1;
    best = Math.max(best, ll + rr);
    return Math.max(ll, rr);
  }
}

